code.iterators:
void iteratorFunction() {
    vector<int> vec = {1, 2, 3, 4};

    // begin() points at the first element
    vector<int>::iterator beginItr = vec.begin();
    cout << *beginItr << endl;

    // end() is one position AFTER the last element. Never dereference it.
    auto endItr = vec.end();
    for (auto i = beginItr; i != endItr; i++) {   // != works for every container
        cout << *i << " ";
    }
    cout << endl;

    // Range-based for loop (uses iterators behind the scenes)
    for (auto x : vec) cout << x << " ";
    cout << endl;

    // Reverse iterators: rbegin() = last element, rend() = before the first
    for (auto i = vec.rbegin(); i != vec.rend(); i++) {
        cout << *i << " ";
    }
    cout << endl;
}

