void vectorFunction() {
    vector<int> vec;              // empty, grows as needed
    vec.push_back(1);
    vec.push_back(2);
    vec.push_back(3);
    vec.emplace_back(4);          // builds the element in place
    cout << vec.size() << endl;

    vector<int> vec1(5);          // 5 zeros
    for (auto i : vec1) cout << i << " ";
    cout << endl;

    vector<int> vec2 = {3, 4, 5, 6};
    vector<int> dupVec(vec2);                         // full copy
    vector<int> dupVec1(vec2.begin() + 1, vec2.end()); // copy of 4 5 6
    for (auto i : dupVec1) cout << i << " ";
    cout << endl;

    vector<int> vec3 = {7, 4, 5, 6, 3, 0};
    cout << vec3.front() << " " << vec3.back() << endl;
    vec3.pop_back();              // removes 0

    vector<int> vec4 = {1, 2, 3, 4, 5, 6};
    vec4.erase(vec4.begin());                      // 2 3 4 5 6
    vec4.erase(vec4.begin() + 1, vec4.end() - 1);  // 2 6
    for (auto i : vec4) cout << i << " ";
    cout << endl;

    vector<int> vec5 = {1, 2, 3};
    cout << vec5[0] << " " << vec5.at(1) << endl;  // at() checks bounds

    vector<int> vec6 = {7, 8}, vec7 = {6, 4};
    swap(vec6, vec7);
    cout << vec6[0] << " " << vec7[0] << endl;

    vector<int> vec8 = {7, 5, 4, 3, 2, 6};
    vec8.insert(vec8.begin(), 1);  // insert(position, value)
    for (auto i : vec8) cout << i << " ";
    cout << endl;

    vec8.clear();                  // size 0, capacity stays
    cout << vec8.size() << endl;
}

