void stackFunction() {
    // LIFO: last in, first out
    stack<int> st;
    st.push(1);
    st.push(2);
    cout << st.size() << endl;
    cout << st.top() << endl;

    st.pop();
    st.pop();
    // st.top() here would be undefined behavior: the stack is empty.
    if (!st.empty()) cout << st.top() << endl;

    stack<int> st1;
    st1.push(5);
    st1.push(8);
    st1.push(6);
    st1.push(3);

    while (!st1.empty()) {
        cout << st1.top() << " ";
        st1.pop();
    }
    cout << endl;
}

