code.pq:
void priorityQueuePQ() {
    // Max-heap by default: the largest element sits on top
    priority_queue<int> pq;
    pq.push(5);
    pq.push(2);
    pq.push(10);
    pq.push(8);
    pq.push(6);

    cout << pq.top() << endl;
    while (!pq.empty()) {
        cout << pq.top() << " ";
        pq.pop();
    }
    cout << endl;

    // Min-heap: smallest element on top
    priority_queue<int, vector<int>, greater<int>> spq;
    for (int x : {5, 2, 10, 8, 6}) spq.push(x);

    while (!spq.empty()) {
        cout << spq.top() << " ";
        spq.pop();
    }
    cout << endl;
}

code.set:
void setDS() {
    // Unique elements, always sorted ascending
    set<int> st;
    st.insert(12);
    st.insert(8);
    st.insert(21);
    st.insert(12);          // duplicate, ignored
    for (auto i : st) cout << i << " ";
    cout << endl;

    auto it = st.find(12);  // returns st.end() when missing
    if (it != st.end()) cout << *it << endl;

    cout << st.count(21) << endl;   // 1 if present, else 0

    st.erase(12);
    for (auto i : st) cout << i << " ";
    cout << endl;

    set<int> st3 = {2, 21, 12, 211, 213};
    auto it1 = next(st3.begin());   // points at 12
    auto it2 = prev(st3.end());     // points at 213
    st3.erase(it1, it2);            // removes 12 21 211
    for (auto x : st3) cout << x << " ";
    cout << endl;

    set<int> st4 = {2, 21, 12, 211, 213};
    auto lb = st4.lower_bound(11);  // first element >= 11
    if (lb != st4.end()) cout << *lb << endl;

    auto ub = st4.upper_bound(214); // first element > 214
    if (ub == st4.end()) cout << "Pointing to end" << endl;
    else cout << *ub << endl;       // check BEFORE dereferencing
}

