code.perm:
void permutations() {
    // Start from sorted order to get ALL permutations
    string str = "abc";
    do {
        cout << str << " ";
    } while (next_permutation(str.begin(), str.end()));
    cout << endl;

    // Only permute the first two characters
    string str1 = "abc";
    do {
        cout << str1 << " ";
    } while (next_permutation(str1.begin(), str1.end() - 1));
    cout << endl;

    // prev_permutation walks backwards, so start from descending order
    string str2 = "cba";
    do {
        cout << str2 << " ";
    } while (prev_permutation(str2.begin(), str2.end()));
    cout << endl;
}

