code.comparator:
// Return true when ele1 must come BEFORE ele2.
// Must be strict: equal elements return false.
bool internalComparator(int ele1, int ele2) {
    return ele1 > ele2;          // descending order
}

bool complexComparator(pair<int, int> a, pair<int, int> b) {
    if (a.second > b.second) return true;   // bigger second first
    if (a.second < b.second) return false;
    return a.first < b.first;               // tie: smaller first first
}

void comparatorDemo() {
    int nums[4] = {5, 6, 1, 2};
    sort(nums, nums + 4, internalComparator);
    for (int i = 0; i < 4; i++) cout << nums[i] << " ";
    cout << endl;

    pair<int, int> ps[5] = {{1, 6}, {1, 5}, {2, 6}, {2, 9}, {3, 9}};
    sort(ps, ps + 5, complexComparator);
    for (auto &p : ps) cout << p.first << " -> " << p.second << endl;
}

