    // Sum of v[l..r] in O(1): pre[r] - pre[l - 1]
    int l = 2, r = 4;
    cout << pre[r] - (l ? pre[l - 1] : 0) << endl;  // 4 + 1 + 5 = 10

    vector<int> diff(v.size());
    adjacent_difference(v.begin(), v.end(), diff.begin());
    for (int x : diff) cout << x << " ";
    cout << endl;
}

